"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[4901],{2498(e){e.exports=JSON.parse('{"title":"\uc65c JS\ub294 \ud544\uc694\uc5c6\ub294 \uc758\uc874\uc131\uc774 \ub9ce\uc744\uae4c","date":"2026-03-31","coverUrl":"/kudzu-based-bench/assets/notion/74ae78e872313f6b.png","html":"<h1 data-notion-block-id=\\"32ce548d-8a8e-803e-9aaf-d0777eb6afe6\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"32ce548d-8a8e-8042-9f1b-cb2439cbdcbb\\" id=\\"32ce548d-8a8e-8042-9f1b-cb2439cbdcbb\\">\uc65c JS\ub294 \ud544\uc694\uc5c6\ub294 \uc758\uc874\uc131\uc774 \ub9ce\uc744\uae4c</h2><a href=\\"https://43081j.com/2026/03/three-pillars-of-javascript-bloat\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://43081j.com/2026/03/three-pillars-of-javascript-bloat</a><p data-notion-block-id=\\"334e548d-8a8e-8055-be31-f579760dd726\\"><a href=\\"https://ones-to-watch.ethansup.net/news/post/43f27c92-8790-48e3-904c-82a7fab89e70#8d21a27c-c00e-4e7c-a4a9-4786e0ac9750\\">E18E</a>\uc758 \ub9ac\ub4dc\uac00 \uc791\uc131\ud55c \uc790\ubc14\uc2a4\ud06c\ub9bd\ud2b8\uac00 \ud544\uc694\uc5c6\uc774 \ube44\ub300\ud574\uc9c0\ub294 \uc774\uc720\ub97c \uc138 \uac00\uc9c0 \ubd84\ub958\ub85c \ub098\ub204\uc5b4\uc11c \uc124\uba85\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. E18E \ucee4\ubba4\ub2c8\ud2f0\uc5d0\uc11c \ub77c\uc774\ube0c\ub7ec\ub9ac\ub4e4\uc758 \uae00\uc5d0\uc11c \uc9da\uc5b4\uc8fc\ub294 \ud544\uc694\uc5c6\ub294 \uc758\uc874\uc131 \ube44\ub300\uc99d\uc744 \uad00\ub9ac\ud558\ub824 \ud558\uace0 \uc788\uc9c0\ub9cc, \ucee4\ubba4\ub2c8\ud2f0 \ucc28\uc6d0\uc758 \uc6c0\uc9c1\uc784\uc5d0 \uae30\ub300\uc9c0 \ub9d0\uace0, \uc774\uc804\uc758 <a href=\\"https://ones-to-watch.ethansup.net/news/post/164e548d-8a8e-80b6-83ab-e98e54c0407f#168e548d-8a8e-8085-806e-c3f848c70e6e\\">\uacc4\uc18d \uac1c\ubc1c\uc744 \uc9c0\uc18d\ud558\uae30 \uc704\ud574\uc11c</a> \uae00\uc5d0\uc11c \uc18c\uac1c\ud588\ub358 \uae00\ucc98\ub7fc, \uadf8\ub9ac\uace0 \ud574\ub2f9 \uae00\uc5d0\uc11c \uc18c\uac1c\ud558\ub294 CLI \ud234\ub4e4\uc744 \uc0ac\uc6a9\ud558\ub294 \uac83\uc744 \uad8c\uc7a5\ud558\ub294 \uac83\ucc98\ub7fc, \uc8fc\uae30\uc801\uc73c\ub85c \uc758\uc874\uc131\uc744 \uad00\ub9ac\ud574\uc57c \ud568\uc744 \uae00\uc774 \uc0c1\uae30\uc2dc\ucf1c\uc90d\ub2c8\ub2e4. \ube44\uc2b7\ud558\uac8c \uc6b0\ub9ac\uac00 \ub9e4\uc77c \uc4f0\ub294 CI/CD \ud234\ub4e4\ub3c4 \uc0ac\uc2e4 \ud328\ud0a4\uc9c0 \ub9e4\ub2c8\uc800\uc640 <a href=\\"https://nesbitt.io/2026/03/08/if-it-quacks-like-a-package-manager.html\\">\uac19\uc740 \ubb38\uc81c\ub97c \uac16\uace0 \uc788\uc2b5\ub2c8\ub2e4</a>. GitHub Actions, Ansible, Terraform, Helm\ucc98\ub7fc \'\ud50c\ub7ec\uadf8\uc778 \uc2dc\uc2a4\ud15c\'\uc774\ub77c \ubd88\ub9ac\ub294 \ud234\ub4e4\ub3c4 \uc758\uc874\uc131 \ud2b8\ub9ac\ub97c \uac16\uace0 \uc788\uace0, lockfile\ub3c4 \uc5c6\uace0, \ubb34\uacb0\uc131 \uac80\uc99d\ub3c4 \ubd80\uc871\ud55c \ucc44\ub85c \uc6b4\uc601\ub418\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc2e4\uc81c\ub85c \uc758\uc874\uc131 \uae4a\uc219\ud55c \uacf3\uc5d0\uc11c supply chain \uacf5\uaca9\uc774 \uc2dc\uc791\ub3fc 23,000\uac1c \uc774\uc0c1\uc758 \ub808\ud3ec\uac00 \uc601\ud5a5\uc744 \ubc1b\uae30\ub3c4 \ud588\uc2b5\ub2c8\ub2e4. \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158 \uac1c\ubc1c\uc790\ub4e0, \ub77c\uc774\ube0c\ub7ec\ub9ac \uac1c\ubc1c\uc790\ub4e0 \uc758\uc874\uc131\uc744 \ucd94\uac00/\uc720\uc9c0\ud560 \ub54c \uad00\ub9ac\ud574\uc57c \ud568\uc744 \uba85\uc2ec\ud574\uc57c\uaca0\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"32ce548d-8a8e-8028-b0d1-c5159fc9edad\\" id=\\"32ce548d-8a8e-8028-b0d1-c5159fc9edad\\">\uc65c \ub9ce\uc740 \\"\uc6d0\uce59\\"\ub4e4\uc740 \uc2e4\ud328\ud558\ub294\uac00</h2><a href=\\"https://principles.design/articles/why-most-design-principles-fail\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://principles.design/articles/why-most-design-principles-fail</a><p data-notion-block-id=\\"333e548d-8a8e-80e6-85f9-e82d13a27636\\">\ub514\uc790\uc778 \uc6d0\uce59\uc774 \ubcbd\uc5d0 \ubd99\uc5b4\uc788\ub294 \uc2ac\ub85c\uac74\uc73c\ub85c \ub05d\ub098\ub294 \uc774\uc720\ub97c \ubd84\uc11d\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \\"\ub2e8\uc21c\ud558\uac8c \ub9cc\ub4e4\uc5b4\ub77c\\"\ucc98\ub7fc \uc758\ub3c4\ub97c \uc124\uba85\ud558\ub294 \ubb38\uc7a5\uc740 \uc6d0\uce59\uc774 \uc544\ub2c8\ub77c \uad6c\ud638\uc785\ub2c8\ub2e4. <a href=\\"https://ones-to-watch.ethansup.net/news/post/bab36975-b9d2-474a-b5a9-babe0f64cb01#94aa8484-fa6b-4f26-aa0b-4a1d93e7b5cd\\">React\uc640 SOLID \uc6d0\uce59</a>\uc5d0\uc11c\ub3c4 \ube44\uc2b7\ud55c \ub9e5\ub77d\uc744 \ub2e4\ub918\uc73c\ub2c8 \uac19\uc774 \ubcf4\uc2dc\ub294 \uac83\uc744 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4. \ub2e8\uc21c\ud788 \ub530\ub77c\uc57c \ud558\ub294 \uaddc\uce59\uc774 \uc544\ub2c8\ub77c \uac19\uc740 \uc5b8\uc5b4\ub85c \ub300\ud654\ud560 \uc218 \uc788\uac8c \ub9cc\ub4dc\ub294 \uc6d0\uce59\uc740 \uc911\uc694\ud569\ub2c8\ub2e4. \uc989 \uc2e4\uc81c \uacb0\uc815 \uc21c\uac04\uc5d0 \uaebc\ub0b4\uace0 \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud560 \uc218 \uc788\uc5b4\uc57c \uc88b\uc740 \uc6d0\uce59\uc774 \ub418\uace0 \uc9c0\uc18d \uac00\ub2a5\ud574\uc9c8\uac81\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"32ee548d-8a8e-802c-a8be-ef08ded5cfc7\\" id=\\"32ee548d-8a8e-802c-a8be-ef08ded5cfc7\\">\uba40\ud2f0 \ube0c\ub79c\ub4dc \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c, \ud1a0\ud070 \ubd84\ub9ac\ubd80\ud130 \uc2dc\uc791\ud558\uae30</h2><a href=\\"https://zeroheight.com/blog/opinionated-vs-global-design-tokens-simplifying-multi-brand-design-systems/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://zeroheight.com/blog/opinionated-vs-global-design-tokens-simplifying-multi-brand-design-systems/</a><p data-notion-block-id=\\"334e548d-8a8e-8054-bff1-f9a96329d854\\">\uba40\ud2f0 \ube0c\ub79c\ub4dc \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc5d0\uc11c \ud1a0\ud070\uc744 \uc5b4\ub5bb\uac8c \uad6c\uc870\ud654\ud560\uc9c0 \uc2e4\ubb34 \uacbd\ud5d8\uc744 \ubc14\ud0d5\uc73c\ub85c \uc124\uba85\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. <a href=\\"https://ones-to-watch.ethansup.net/news/post/2dbe548d-8a8e-8032-b1c2-ec78ab7314d0#2e7e548d-8a8e-80c6-b145-e2b80e917782\\">Spotify\uc758 Encore \uc2e4\ud328 \uacbd\ud5d8</a>\uacfc \uac19\uc774 \uc77d\uac8c \ub418\uba74, \ud070 \ud68c\uc0ac\uc5d0 \ub9de\uac8c \ub418\ub294 \uba40\ud2f0 \ube0c\ub79c\ub4dc, \uba40\ud2f0 \ud300 \ud658\uacbd\uc5d0\uc11c \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c \ud655\uc7a5\uc131\uc744 \uc5b4\ub5bb\uac8c \uc313\uc544\uac08\uc9c0 \uace0\ubbfc\ud558\uae30\uc5d0 \uc88b\uc2b5\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"32ce548d-8a8e-803c-a6fc-dfb5e5630d67\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"32ee548d-8a8e-8039-9222-e562ecef8093\\" id=\\"32ee548d-8a8e-8039-9222-e562ecef8093\\">\uacfc\ub3c4\ud55c disabled \uc0ac\uc6a9\uc740 UX\uc5d0 \ud574\uac00 \ub41c\ub2e4.</h2><a href=\\"https://zeroheight.com/blog/rethinking-the-disabled-norm/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://zeroheight.com/blog/rethinking-the-disabled-norm/</a><p data-notion-block-id=\\"32ee548d-8a8e-80be-9044-f8ead4162cc0\\">disabled\uc758 \uacfc\ub2e4\ud55c \uc0ac\uc6a9\uc740 UX\uc5d0 \ud574\uac00 \ub418\uba70, \uc774\ub97c \ud574\uacb0\ud558\uae30 \uc704\ud55c 7\uac00\uc9c0 \ud574\uacb0\ucc45\uc744 \uc81c\uc2dc\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ud3fc \ubd80\ubd84\uc5d0\uc11c disabled\ub97c \ub9ce\uc774 \uc0ac\uc6a9\ud558\uace0 \uc788\ub2e4\uba74, \uae00\uc744 \ubcf4\uace0 \uc9da\uace0 \ub118\uc5b4\uac00\uc57c \ud560 \uac83 \uac19\ub124\uc694!</p><h2 data-notion-block-id=\\"32fe548d-8a8e-80ca-9cc8-eba72eb5e690\\" id=\\"32fe548d-8a8e-80ca-9cc8-eba72eb5e690\\">Test ID == \uc811\uadfc\uc131 \ud30c\uad34</h2><a href=\\"https://tkdodo.eu/blog/test-ids-are-an-a11y-smell\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tkdodo.eu/blog/test-ids-are-an-a11y-smell</a><p data-notion-block-id=\\"334e548d-8a8e-8061-959e-c2cd1be30b48\\"><code>data-testid</code>\uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ud14c\uc2a4\ud2b8 \uc804\uc6a9 ID\ub97c \uc0bd\uc785\ud558\ub294 \uac83\uc740 UX/\uc811\uadfc\uc131\uc5d0 \uc2ec\uac01\ud55c \uc601\ud5a5\uc744 \ub07c\uce5c\ub2e4\ub294 \uc8fc\uc7a5\uc758 \uae00\uc785\ub2c8\ub2e4. \ub0b4\ubd80 \uad6c\ud604\uc744 \uc9c1\uc811 \ud14c\uc2a4\ud2b8\ud558\ub294 \ubc29\uc2dd\uc778 Enzyme\uc5d0\uc11c \ud589\ub3d9\uc744 \ud14c\uc2a4\ud2b8\ud558\ub294 RTL\ub85c \ub9ce\uc774 \ub118\uc5b4\uac04 \ub9cc\ud07c, \ub0b4\ubd80 \uad6c\ud604\uc744 \uc9c1\uc811 \ud14c\uc2a4\ud2b8 \ucf54\ub4dc\uc5d0 \uc0bd\uc785\ud558\ub294 \uac83\uc774 \uc544\ub2cc, \ud589\ub3d9\uc744 \ud14c\uc2a4\ud2b8\ud574\uc57c \ud55c\ub2e4\ub294 \uc810\uc744 \uba85\uc2ec\ud574\uc57c\uaca0\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"32fe548d-8a8e-8037-b8a5-ca8fa2e03ce0\\" id=\\"32fe548d-8a8e-8037-b8a5-ca8fa2e03ce0\\">Color \ud1a0\ud070\uc740 \ub450 \ubd84\ub958\ub85c \ub098\ub25c\ub2e4.</h2><a href=\\"https://theadminbar.com/semantics-and-primitives-color-system/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://theadminbar.com/semantics-and-primitives-color-system/</a><p data-notion-block-id=\\"333e548d-8a8e-80b6-a1ab-fe06d5ea2a66\\">primitive \ud1a0\ud070/semantic \ud1a0\ud070\uc758 \uac1c\ub150\uc744 \uc124\uba85\ud558\uace0, \ub2e8\uc21c\ud788 \ud558\ub4dc\ucf54\ub529\ud558\ub294 \uac83\uc774 \uc544\ub2c8\uace0, \ud55c \uac1c\ub150\ub9cc \uc0ac\uc6a9\ud558\ub294 \uac83\uc774 \uc544\ub2cc \ub450 \uac1c\ub150 \ubaa8\ub450 \uc0ac\uc6a9\ud574\uc57c \ud558\ub294 \uc774\uc720\ub97c \ub2e4\ub8e8\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"32fe548d-8a8e-80ad-aae3-cf35467cd38a\\" id=\\"32fe548d-8a8e-80ad-aae3-cf35467cd38a\\">CI\uc5d0\uc11c Jest\ub97c \uc2e4\ud589\ud560 \uacbd\uc6b0 \uc870\uc2ec\ud574\uc57c \ud558\ub294 \uc124\uc815</h2><a href=\\"https://shift.infinite.red/fix-flaky-jest-tests-in-ci-with-maxworkers-and-why-it-works-e3d3189f35a4\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://shift.infinite.red/fix-flaky-jest-tests-in-ci-with-maxworkers-and-why-it-works-e3d3189f35a4</a><h2 data-notion-block-id=\\"334e548d-8a8e-8000-841a-db219615301d\\" id=\\"334e548d-8a8e-8000-841a-db219615301d\\">Sticky \ud5e4\ub354 \ubc30\uacbd CSS \ud2b8\ub9ad</h2><a href=\\"https://www.joshwcomeau.com/css/header-blockers/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.joshwcomeau.com/css/header-blockers/</a><h2 data-notion-block-id=\\"330e548d-8a8e-809e-b405-e192f22cc124\\" id=\\"330e548d-8a8e-809e-b405-e192f22cc124\\">Multi-pod Node.js \ud658\uacbd\uc5d0\uc11c \uc911\uc694\ud55c \uc124\uc815</h2><a href=\\"https://frn.sh/pmem/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://frn.sh/pmem/</a><h2 data-notion-block-id=\\"32ce548d-8a8e-8071-a31e-c007c261f924\\" id=\\"32ce548d-8a8e-8071-a31e-c007c261f924\\">Node.js \ucf54\uc5b4 \ub2e8\uc5d0\uc11c DoS \ub300\ube44 \uc124\uacc4\ud558\uae30</h2><a href=\\"https://nodejs.org/en/blog/vulnerability/march-2026-hashdos\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nodejs.org/en/blog/vulnerability/march-2026-hashdos</a><p data-notion-block-id=\\"334e548d-8a8e-809f-95af-c5ea5a39eed4\\">\ud574\uc2dc \ucda9\ub3cc\uc744 \uc774\uc6a9\ud55c DoS \uacf5\uaca9(HashDoS)\uc5d0 \ub300\uc751\ud558\uba74\uc11c\ub3c4 \ube60\ub974\uac8c \ub418\ub3cc\ub9b4 \uc218 \uc788\ub294 \uc815\uc218 \ud574\uc2dc \ud568\uc218\ub97c V8\uc5d0 \ub9de\uac8c \uc124\uacc4\ud55c \uacfc\uc815\uc744 \uc124\uba85\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ubcf4\uc548\uacfc \uc131\ub2a5 \uc0ac\uc774\uc758 \ud2b8\ub808\uc774\ub4dc\uc624\ud504\ub97c Node.js \ucf54\uc5b4 \ud300\uc774 \uc5b4\ub5bb\uac8c \ub2e4\ub918\ub294\uc9c0 \uc5ff\ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"32ee548d-8a8e-801f-abe4-d23b2b6ea730\\" id=\\"32ee548d-8a8e-801f-abe4-d23b2b6ea730\\">Man vs \ubb38\uc11c\ud654 in design system</h2><a href=\\"https://zeroheight.com/blog/why-your-design-system-documentation-goes-stale/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://zeroheight.com/blog/why-your-design-system-documentation-goes-stale/</a><p data-notion-block-id=\\"32ce548d-8a8e-801c-8db6-f6fb320aed1c\\">\ub514\uc790\uc778 \uc2dc\uc2a4\ud15c \ud300\uc774 \ud56d\uc0c1 \uacbd\uacc4\ud558\ub294 \u201c\ubb38\uc11c\ub97c \ucd5c\uc2e0\ud654\ub85c \uc5b4\ub5bb\uac8c \uc720\uc9c0\ud560\uae4c\u201d\ub97c \uc5b4\ub5a4 \ubd80\ubd84\ubd80\ud130 \uc2dc\uc791\ud574\uc57c \ud558\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"32ce548d-8a8e-80c6-8725-c5e2350afa89\\">Fresh Finds: \ub193\uce58\uc9c0 \ub9d0\uc544\uc57c \ud560 \uc18c\uc2dd</h1><a href=\\"https://heroui.com/docs/react/releases/v3-0-0\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://heroui.com/docs/react/releases/v3-0-0</a><p data-notion-block-id=\\"333e548d-8a8e-80fa-946c-e504c424a5ea\\">NextUI\uac00 HeroUI\ub85c \ub9ac\ube0c\ub79c\ub529\ud558\uba74\uc11c v3\ub97c \ucd9c\uc2dc\ud588\uc2b5\ub2c8\ub2e4.</p><a href=\\"https://nextjs.org/blog/nextjs-across-platforms\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nextjs.org/blog/nextjs-across-platforms</a><p data-notion-block-id=\\"333e548d-8a8e-8036-ba05-c4bd133fe397\\">Vercel\uc774 Next.js\ub97c \ub2e4\uc591\ud55c \ud50c\ub7ab\ud3fc\uc5d0\uc11c \uc2e4\ud589\ud560 \uc218 \uc788\ub3c4\ub85d \uc5b4\ub311\ud130 \uc2dc\uc2a4\ud15c\uacfc OpenNext\uc5d0 \ub300\ud55c \uacf5\uc2dd \uc785\uc7a5\uc744 \ubc1c\ud45c\ud588\uc2b5\ub2c8\ub2e4.</p><a href=\\"https://github.com/chenglou/pretext\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/chenglou/pretext</a><p data-notion-block-id=\\"334e548d-8a8e-8079-8cfa-f3458d8cd046\\"> DOM \ub808\uc774\uc544\uc6c3 reflow \uc5c6\uc774 \uba40\ud2f0\ub77c\uc778 \ud14d\uc2a4\ud2b8\uc758 \ub192\uc774\uc640 \uc904 \uc218\ub97c \uce21\uc815\ud560 \uc218 \uc788\ub294 \uc21c\uc218 JS/TS \ub77c\uc774\ube0c\ub7ec\ub9ac\ub85c, \ube0c\ub77c\uc6b0\uc800 \ud3f0\ud2b8 \uc5d4\uc9c4\uc744 \uae30\ubc18\uc73c\ub85c \uc9c1\uc811 \ud14d\uc2a4\ud2b8 \ub808\uc774\uc544\uc6c3 \ub85c\uc9c1\uc744 \uad6c\ud604\ud588\uc2b5\ub2c8\ub2e4. </p>"}')}}]);